        # $100 split 4 ways
        assert split_payment(100, 4) == [25, 25, 25, 25]

    def test_remainder_distribution_order(self):
        # $10 split 3 ways: 10 // 3 = 3, remainder 1.
        # First participant gets +1.
        assert split_payment(10, 3) == [4, 3, 3]

