        assert split_payment(0, 5) == [0, 0, 0, 0, 0]

    def test_invalid_num_participants(self):
        with pytest.raises(ValueError):
            split_payment(100, 0)

    def test_negative_total(self):
        with pytest.raises(ValueError):
            split_payment(-100, 2)

